<template><div><PageHeader title="Trainers" description="Manage trainers, expertise and assigned sessions."><template #actions><button class="btn primary" @click="addOpen=true">+ Add trainer</button></template></PageHeader><div class="course-grid"><div v-for="trainer in trainers" :key="trainer.id" class="course-card"><div class="course-top"><Avatar :name="trainer.name" size="lg"/><StatusBadge :status="trainer.status"/></div><h3>{{trainer.name}}</h3><p>{{trainer.specialty}}</p><div class="info-list"><div class="info-box"><span>Courses</span><strong>{{trainer.courses}}</strong></div><div class="info-box"><span>Batches</span><strong>{{trainer.batches}}</strong></div></div><div class="course-bottom" style="margin-top:16px"><button class="btn secondary small" style="width:100%">View trainer</button></div></div></div><Modal :open="addOpen" title="Add trainer" description="Create a trainer profile" @close="addOpen=false"><form class="auth-form" @submit.prevent="save"><div class="field"><label>Name</label><input class="input" v-model="form.name"></div><div class="field"><label>Email</label><input class="input" v-model="form.email"></div><div class="field"><label>Specialization</label><input class="input" v-model="form.specialty"></div><div class="form-actions" style="padding:16px 0 0;border:0"><button type="button" class="btn secondary" @click="addOpen=false">Cancel</button><button class="btn primary">Create trainer</button></div></form></Modal></div></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import Avatar from '../components/Avatar.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {trainers} from '../data/mock';import {useToast} from '../composables/useToast';const addOpen=ref(false);const form=reactive({name:'',email:'',specialty:''});const {push}=useToast();function save(){addOpen.value=false;push('Trainer created successfully.')}</script>
